Identify the original data block in Sheet1 as the contiguous rows after the header where column A is non-empty.  
Duplicate each row according to its AG count, preserving order and inserting copies immediately below the source row.  
Write the reference header (or the source header if no reference header is present) and the duplicated rows into Sheet2 A1:AG10 as plain values.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

src = vals["Sheet1"]
if "Sheet2" in wb.sheetnames:
    out = wb["Sheet2"]
else:
    out = wb.create_sheet("Sheet2")

NCOLS = 33
ANSWER_ROWS = 10

def clean(v):
    if isinstance(v, str):
        v = v.strip()
        if v == "":
            return None
    return v

# Clear the graded answer region first.
for r in range(1, ANSWER_ROWS + 1):
    for c in range(1, NCOLS + 1):
        out.cell(row=r, column=c).value = None

# Find the original data rows: contiguous non-empty column A starting at row 2.
data_rows = []
for r in range(2, src.max_row + 1):
    v = src.cell(row=r, column=1).value
    if v is None or (isinstance(v, str) and v.strip() == ""):
        break
    data_rows.append(r)

# Prefer the reference result header if it exists below the input table.
header_row = 1
search_start = (data_rows[-1] + 1) if data_rows else 2
for r in range(search_start, src.max_row + 1):
    if (
        clean(src.cell(row=r, column=1).value) == "Col1"
        and clean(src.cell(row=r, column=NCOLS).value) == "COUNT"
    ):
        header_row = r
        break

# Write header.
for c in range(1, NCOLS + 1):
    out.cell(row=1, column=c).value = clean(src.cell(row=header_row, column=c).value)

# Duplicate data rows according to column AG.
out_r = 2
for r in data_rows:
    cnt = src.cell(row=r, column=NCOLS).value
    if cnt is None:
        n = 1
    else:
        try:
            n = int(float(cnt))
        except (TypeError, ValueError):
            n = 1
        if n < 0:
            n = 0

    for _ in range(n):
        if out_r > ANSWER_ROWS:
            break
        for c in range(1, NCOLS + 1):
            out.cell(row=out_r, column=c).value = clean(src.cell(row=r, column=c).value)
        out_r += 1

    if out_r > ANSWER_ROWS:
        break

wb.save(OUT)

print("data_rows:", data_rows)
print("header_row:", header_row)
print("output_rows_written:", out_r - 1)
print("first_data_row:", [out.cell(row=2, column=c).value for c in range(1, 6)])
